statements.inv:A3.1:
\begin{proposition}[The complete Hodge table for every admissible parameter]\hypertarget{tag-01RY}{}\label{inv:A3.1}\label{wb:cor:exact-hodge-diamond}\label{wb:thm:parametric-hodge-diamond}\label{wb:prop:workbench-holomorphic-form-vanishing}
\StatementRecord{inv:A3.1}{proved}{01RY}{\SeriesRef{inv:eq:A-absolute-table}, \SeriesRef{inv:A1.0}}

For every $\operatorname{Im}c<-M$, the Hodge numbers are
\[
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&1&2&1\\
1&1&2&1&0\\
0&1&0&0&0.
\end{array}
\]
\end{proposition}

statements.inv:C2.1:
\begin{proposition}[Bott--Chern and Aeppli tables as functions of $h$]\hypertarget{tag-01SC}{}\label{inv:C2.1}\label{wb:thm:exact-bott-chern-aeppli}
\StatementRecord{inv:C2.1}{proved}{01SC}{\SeriesRef{inv:A3.1}, \SeriesRef{inv:C1.1}, \SeriesRef{inv:eq:C-arrows}; \citet[Theorem 3]{Stelzig2021}; \citet[Proposition 6(1)]{Stelzig2021}}

The complete dimension tables are
\begin{equation}\hypertarget{tag-01T6}{}\label{inv:eq:C-BC-A}
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&1&1\\
2&0&h&2h&1\\
1&0&2&h&0\\
0&1&0&0&0
\end{array}_{BC}
\qquad
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&h&2&0\\
1&1&2h&h&0\\
0&1&1&0&0.
\end{array}_{A}
\end{equation}
At the value $h=1$ of Proposition~\ref{inv:A3.1},  The totals are
$(1,0,2,2,2,2,1)$ and $(1,2,2,2,2,0,1)$, respectively.
\end{proposition}

statements.inv:A4.2:
\begin{proposition}[The support of relative torsion]\hypertarget{tag-01S1}{}\label{inv:A4.2}
\StatementRecord{inv:A4.2}{proved}{01S1}{\SeriesRef{inv:A4.1}}

The torsion of $\Omega_{X/B}^1$ is supported precisely on
$S_1\cup S_2$. Its cusp modules inject into the free logarithmic
relative modules, and their minimal number of generators exceeds
their rank at the double locus. In degree two, the torsion also
has support on the cusp double locus.
This corrects \cite[Remark~9.21, p.~81]{AC2026}, where
degree-one torsion is asserted on $W\cup S_1\cup S_2$;
the support statement in \cite[Remark~1.3, p.~5]{AC2026}
therefore depends on the degree.
\end{proposition}

statements.inv:D4.2:
\begin{proposition}[The cusp length and the generic twist]\hypertarget{tag-01SP}{}\label{inv:D4.2}
\StatementRecord{inv:D4.2}{proved}{01SP}{\SeriesRef{inv:C3.2}, \SeriesRef{inv:D4.3}, \SeriesRef{inv:D1.2}}

Use the coordinate $M_z=\exp(z\mathfrak g)$ of \ref{inv:C3.2}. For every
$z\notin\Z$ the cusp contribution is exactly
\[
 (R^0f_*(T_X\otimes M_z))_{p_0}=0,\quad
 (R^1f_*(T_X\otimes M_z))_{p_0}=0,\quad
 (R^2f_*(T_X\otimes M_z))_{p_0}=\C\{q\}/(q).           \tag{D.14}
\]
Outside the countable exceptional set explicitly defined in \ref{inv:D4.3},
these are the only nonzero direct-image stalks. Hence the generic
twist has $(h^0,h^1,h^2,h^3)=(0,0,1,0)$, and the cusp nilpotence exponent $r$ equals one there.
\end{proposition}

statements.fam:src:B.4.1:
\begin{theorem}[The full automorphism group]\hypertarget{tag-01QF}{}\label{fam:src:B.4.1}\label{fam:st:B.4.1}\hypertarget{tag-02YQ}{}\label{night:P5.5}\label{stmt:P5.5}
\StatementRecord{night:P5.5}{proved}{02YQ}{the definitions and constructions stated in the proof}

For every admissible twist of the $(3,4)$ construction,
\[
 \operatorname{Aut}(X_c)=\mathbb C/\mathbb Z\simeq\mathbb C^*.
\]
The parameter $a\bmod\mathbb Z$ acts by $\zeta\mapsto\zeta+ae$,
where $e=\Pi_c\widehat\delta$. The exponential group isomorphism
is $a\bmod\mathbb Z\mapsto e^{2\pi ia}$.
\end{theorem}

statements.inv:C3.2:
\begin{proposition}[The factor $12$ with a fixed collar orientation]\hypertarget{tag-01SF}{}\label{inv:C3.2}\label{wb:lem:bcpr-degree-one-input}
\StatementRecord{inv:C3.2}{proved}{01SF}{\SeriesRef{inv:eq:C-collar-sum}, \SeriesRef{inv:C3.1}}

Use the marked cohomology class $\gamma$ dual to
$\hat\gamma$, the analytic peripheral generators and the lift relation of
\cite[\S7.5, pp.~54--57, especially (7.10), p.~55]{AC2026}, and put
$p=12l_0-4l_1-3l_2=\pm1$.  Let $g_\gamma$ be the unique coherent
Leray class whose fibre image is $\gamma^{0,1}$.  Then
\begin{equation}\hypertarget{tag-01TE}{}\label{inv:eq:C-factor12}
\exp(12g_\gamma)=f^*\OO_{\Pone}(-p).
\end{equation}
For the standard data $(l_0,l_1,l_2)=(0,1,-1)$, this is
$\exp(12g_\gamma)=f^*\OO(1)$.  For the opposite value $p=1$,
the exponent representing $f^*\OO(1)$ is $-12g_\gamma$.
\end{proposition}
